import { runFast } from './fast_sim.mjs';

function makeController() {
  let targetIndex = -1, phase = 'climb';
  let ix = 0, iy = 0, iz = 0;
  let vxEst = 0, vyEst = 0, vzEst = 0;
  let axDist = 0, ayDist = 0, azDist = 0;
  let lastCmdAx = 0, lastCmdAy = 0, lastCmdAz = 0;
  let settle = 0, landTimer = 0;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att;
      const dt = 0.01;

      if (obs.t === 0) {
        vxEst = v.x; vyEst = v.y; vzEst = v.z;
      } else {
        // Actual acceleration from velocity change
        const rawAx = (v.x - vxEst) / dt;
        const rawAy = (v.y - vyEst) / dt;
        const rawAz = (v.z - vzEst) / dt;
        vxEst = v.x; vyEst = v.y; vzEst = v.z;

        // Low-pass filter disturbance (actual accel minus commanded accel)
        const alpha = 0.08;
        axDist += alpha * ( clamp(rawAx - lastCmdAx, -15, 15) - axDist );
        ayDist += alpha * ( clamp(rawAy - lastCmdAy, -15, 15) - ayDist );
        azDist += alpha * ( clamp(rawAz - lastCmdAz, -15, 15) - azDist );
      }

      let target, targetVel = { x: 0, y: 0, z: 0 };

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          targetIndex = obs.gateIndex;
          phase = 'align';
          settle = 0;
        }

        const dy = Math.abs(p.y - gate.y);
        const dz = Math.abs(p.z - gate.z);

        // If we accidentally went past the gate without crossing it (or missed it)
        if (p.x > gate.x - 0.05 && phase !== 'cross') {
          phase = 'recover';
        }
        if (phase === 'recover') {
          // Fly around the gate frame safely (above or to the side) back to x = gate.x - 0.55
          const safeZ = gate.z + (p.z >= gate.z ? 0.45 : -0.45);
          if (p.x > gate.x - 0.35) {
            target = { x: gate.x - 0.55, y: gate.y + 0.35, z: clamp(safeZ, -2.6, 2.6) };
          } else {
            phase = 'align';
          }
        }

        if (phase === 'align') {
          // Approach point before gate
          const approachX = gate.x - 0.40;
          target = { x: approachX, y: gate.y, z: gate.z };
          // Check if well aligned in y and z, and close to approachX
          const alignedYZ = dy < 0.065 && dz < 0.065 && Math.abs(v.y) < 0.35 && Math.abs(v.z) < 0.35;
          const nearX = p.x > gate.x - 0.52 && p.x < gate.x - 0.15 && v.x > -0.2 && v.x < 0.7;
          if (alignedYZ && nearX) settle++;
          else settle = Math.max(0, settle - 1);
          if (settle >= 6) phase = 'cross';
        }

        if (phase === 'cross') {
          // Abort cross if wind pushes us out of safe corridor before reaching the gate plane!
          const distToPlane = gate.x - p.x;
          const predY = p.y + v.y * clamp(distToPlane / Math.max(0.4, v.x), 0, 0.35);
          const predZ = p.z + v.z * clamp(distToPlane / Math.max(0.4, v.x), 0, 0.35);
          if (distToPlane > 0.08 && (Math.abs(p.y - gate.y) > 0.14 || Math.abs(p.z - gate.z) > 0.085 || Math.abs(predY - gate.y) > 0.16 || Math.abs(predZ - gate.z) > 0.095)) {
            phase = 'align';
            settle = 0;
            target = { x: gate.x - 0.40, y: gate.y, z: gate.z };
          } else {
            target = { x: gate.x + 0.32, y: gate.y, z: gate.z };
            targetVel = { x: 0.75, y: 0, z: 0 };
          }
        }
      } else {
        const pad = obs.pad.centre;
        const distXZ = Math.hypot(pad.x - p.x, pad.z - p.z);
        const speedXZ = Math.hypot(v.x, v.z);
        if (phase !== 'descend' && phase !== 'touchdown') {
          phase = 'pad_approach';
          target = { x: pad.x, y: 0.65, z: pad.z };
          if (distXZ < 0.12 && speedXZ < 0.28 && p.y < 0.85) {
            phase = 'descend';
          }
        }
        if (phase === 'descend') {
          // Smooth descent toward pad
          const targetY = distXZ < 0.09 ? 0.05 : 0.25;
          target = { x: pad.x, y: targetY, z: pad.z };
          if (p.y <= 0.092 && distXZ <= 0.13 && speedXZ < 0.35 && Math.abs(v.y) < 0.35) {
            phase = 'touchdown';
            landTimer = 0;
          } else if (distXZ > 0.18) {
            phase = 'pad_approach';
