    else {
      reasons[r.reason] = (reasons[r.reason] || 0) + 1;
      fails.push(`seed ${s}: ${r.reason} (gates ${r.gatesPassed}, t=${r.simulatedSeconds})`);
    }
  }
  console.log(`Current /workspace/controller.js: ${pass}/500 (${(pass/5).toFixed(1)}%)`, reasons);
  console.log("Sample fails:", fails.slice(0, 20));
});
